import sys
import numpy as np

def main():
    if len(sys.argv) < 2:
        print("Average: 0.0")
        return

    try:
        numbers = [float(arg) for arg in sys.argv[1:]]
        avg = np.mean(numbers)
        print(f"Average: {avg}")
    except ValueError:
        print("Error: Invalid input")
        sys.exit(1)

if __name__ == "__main__":
    main()

